<?php
$mode=$argv[1];function check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$udp=str_starts_with($mode,'udp');$server=stream_socket_server(($udp?'udp':'tcp').'://127.0.0.1:0',$errno,$error,$udp?STREAM_SERVER_BIND:STREAM_SERVER_BIND|STREAM_SERVER_LISTEN);check(is_resource($server),'listen');echo stream_socket_get_name($server,false),"\n";flush();stream_set_timeout($server,15);
if($udp){$request=stream_socket_recvfrom($server,64,0,$client);check($request==="udp\0request",'UDP request');$response="udp\0reply";check(stream_socket_sendto($server,$response,0,$client)===strlen($response),'UDP reply');$summary=['request_hex'=>bin2hex($request),'response_hex'=>bin2hex($response),'client'=>$client,'peer_closed'=>true];}
else {$connection=stream_socket_accept($server,15);check(is_resource($connection),'accept');stream_set_timeout($connection,15);$response="PEEK\0OK";check(fwrite($connection,$response)===strlen($response),'payload');echo "payload-ready\n";flush();$request='';while(strlen($request)<4){$part=fread($connection,4-strlen($request));check(is_string($part)&&$part!=='','ack');$request.=$part;}check($request==='ack!','exact ack');fclose($connection);echo "peer-closed\n";flush();$summary=['request_hex'=>bin2hex($request),'response_hex'=>bin2hex($response),'peer_fin'=>true];}
fclose($server);echo json_encode($summary,JSON_THROW_ON_ERROR),"\n";
